discrete PhaseDetector
port:
    event input real ReferenceSignal;
    event input real FeedbackSignal;
    event output real ErrorSignal;
state:
    initial state WaitForInput
        when entry() then
            statehold(0);
        end;
        when receive(ReferenceSignal) then
            transition(ComparePhase);
        end;
        when receive(FeedbackSignal) then
            transition(ComparePhase);
        end;
    end;

    state ComparePhase
        when entry() then
            statehold(0);
        end;
        when timeover() then
            transition(WaitForInput);
            out
                send(ErrorSignal, 1);
        end;
    end;
end;
end;

discrete LoopFilter
port:
    event input real ErrorSignal;
    event output real ControlVoltage;
state:
    initial state WaitForInput
        when entry() then
            statehold(0);
        end;
        when receive(ErrorSignal) then
            transition(FilterError);
        end;
    end;

    state FilterError
        when entry() then
            statehold(0);
        end;
        when timeover() then
            transition(WaitForInput);
            out
                send(ControlVoltage, 1);
        end;
    end;
end;
end;

discrete VoltageControlledOscillator
port:
    event input real ControlVoltage;
    event output real OutputFrequency;
state:
    initial state OutputFixedFrequency
        when entry() then
            statehold(0);
        end;
        when receive(ControlVoltage) then
            transition(AdjustFrequency);
        end;
    end;

    state AdjustFrequency
        when entry() then
            statehold(0);
        end;
        when timeover() then
            transition(OutputFixedFrequency);
            out
                send(OutputFrequency, 1);
        end;
    end;
end;
end;

